if (new URLSearchParams(location.search).get("azienda") || document.querySelector("#chat")) {
"use strict";
const controls=document.createElement('details');controls.className='dash-card';const title=document.createElement('summary');title.textContent='Appuntamenti, operatore e voce';controls.append(title);const status=document.createElement('p');status.setAttribute('role','status');const content=document.createElement('div');controls.append(content,status);document.querySelector('#chat-form, #chat').after(controls);
const make=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n};let currentSession;
async function invoke(path,data={}){currentSession=await window.lineaAgentSession();const r=await fetch('/api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,session:currentSession})}),d=await r.json();if(!r.ok)throw Error(d.error);return d}
async function setup(){try{const d=await invoke('agent-state');content.replaceChildren();const caps=d.capabilities,brand=d.branding;const name=document.querySelector('#name');if(name&&brand.assistant_name)name.textContent=brand.assistant_name;if(document.querySelector('#chat')){document.body.style.color=brand.color;document.body.dataset.position=brand.widget_position;if(brand.logo&&!document.querySelector('#company-logo')){const img=make('img');img.id='company-logo';img.src=brand.logo;img.alt='Logo azienda';img.width=100;document.querySelector('header').prepend(img)}if(brand.contact)status.textContent=brand.contact}
if(caps.can_book_appointments){const open=make('button','Appuntamenti di prova');open.type='button';content.append(open);open.onclick=async()=>{try{const r=await invoke('booking-slots');const form=make('div'),select=make('select');select.setAttribute('aria-label','Orario di prova');for(const slot of r.slots){const o=make('option',new Intl.DateTimeFormat('it-IT',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(slot.starts))+' (ora italiana) — '+slot.label);o.value=slot.id;select.append(o)}const label=make('label'),confirm=make('input');confirm.type='checkbox';label.append(confirm,document.createTextNode('Confermo questo appuntamento di prova. Nessuna prenotazione reale.'));const save=make('button','Conferma appuntamento');save.type='button';save.disabled=!r.slots.length;save.onclick=async()=>{try{const result=await invoke('booking-confirm',{slot:select.value,confirm:confirm.checked});status.textContent=result.message;save.disabled=true}catch(e){status.textContent=e.message}};form.append(select,label,save);open.after(form);open.disabled=true;if(!r.slots.length)status.textContent='Non ci sono disponibilità di prova.'}catch(e){status.textContent=e.message}}}
if(caps.can_handoff_to_human){const ask=make('button','Chiedi di parlare con il personale');ask.type='button';ask.onclick=async()=>{try{if(!confirm('Trasferire questa conversazione al personale dell’azienda?'))return;const r=await invoke('request-human',{confirm:true});status.textContent=r.message}catch(e){status.textContent=e.message}};const poll=make('button','Aggiorna risposte operatore');poll.type='button';poll.onclick=async()=>{try{const state=await invoke('agent-state');const list=make('div');for(const m of state.messages)list.append(make('p',(m.role==='human'?'Operatore: ':m.role==='user'?'Tu: ':'Assistente: ')+m.content));content.append(list)}catch(e){status.textContent=e.message}};content.append(ask,poll)}
if(caps.can_use_voice){content.append(make('p','Voce simulata: nessun microfono attivo e nessun audio inviato. Inserisci la trascrizione di prova; la risposta vocale è rappresentata come testo.'));const input=make('textarea');input.setAttribute('aria-label','Trascrizione vocale di prova');const label=make('label'),consent=make('input');consent.type='checkbox';label.append(consent,document.createTextNode('Acconsento a conservare la trascrizione nella stessa conversazione.'));const send=make('button','Invia trascrizione di prova');send.type='button';send.onclick=async()=>{send.disabled=true;try{const r=await invoke('voice-mock',{transcript:input.value,transcript_consent:consent.checked});window.lineaAgentMessage(input.value,'user');window.lineaAgentMessage(r.reply,'assistant');status.textContent='Risposta vocale simulata: '+r.speech.text;input.value=''}catch(e){status.textContent=e.message}finally{send.disabled=false}};content.append(input,label,send)}
if(!caps.can_use_voice&&!caps.can_handoff_to_human&&!caps.can_book_appointments)status.textContent='Questa azienda non ha abilitato azioni aggiuntive.';
}catch(e){status.textContent=e.message}}
controls.addEventListener('toggle',()=>{if(controls.open)setup()});

window.addEventListener('linea-ready',async()=>{try{const d=await invoke('agent-state'),b=d.branding;if(document.querySelector('#name')&&b.assistant_name)document.querySelector('#name').textContent=b.assistant_name;document.body.style.color=b.color;document.body.dataset.position=b.widget_position;for(const kind of ['logo','avatar'])if(b[kind]&&!document.querySelector('#company-'+kind)){const img=make('img');img.id='company-'+kind;img.src=b[kind];img.alt=kind==='logo'?'Logo azienda':'Avatar assistente';img.width=kind==='logo'?100:40;document.querySelector('header').prepend(img)}if(b.contact)status.textContent=b.contact}catch(e){status.textContent=e.message}});

}
